export default async()=>{const t=import.meta.url.replace("wasm-vips-cdn@0.0.17","wasm-vips@0.0.11"),s=new URL("vips-es6.js",t).href,i=new URL("vips.wasm",t).href;let e=await fetch(s).then((a)=>a.ok?a.text():Promise.reject(`Failed to fetch ${s}`));e=e.replaceAll("vips.wasm",i).replace('"vips-es6.js",',"");const r=URL.createObjectURL(new Blob([e],{type:"text/javascript"})),{default:c}=await import(r);return await c({dynamicLibraries:[]})}